check('function migrateV22(raw)' in js and 'raw.schemaVersion === 22' in js,'storage 22 to 23 migration')
check('state.accountPersistence = normalizeAccountPersistence(raw.accountPersistence, state.projects);' in js and 'state.crossDeviceSync = normalizeCrossDeviceSync(raw.crossDeviceSync, state.projects);' in js,'current-state account/sync normalization repaired')
check(manifest['version_history']['named_restore_points'] and manifest['version_history']['restore_mode']=='new-local-copy','named restore points / restore as copy')
check(not manifest['version_history']['overwrite_current_project'] and not manifest['version_history']['automatic_cloud_upload'],'no overwrite / no automatic upload')
