check('Compare current' in js and "verify.textContent='Verify'" in js and "exp.textContent='Export'" in js,'compare verify export controls')
check("const CROSS_DEVICE_SYNC_SCHEMA = 'sc-workspace-cross-device-sync/1.0'" in js and "'/sync-contract'" in php,'v0.22 sync retained')
check("const ACCOUNT_PERSISTENCE_SCHEMA = 'sc-workspace-account-persistence/1.0'" in js and "'/account-persistence-contract'" in php,'v0.21 account persistence retained')
check("const LAST_GOOD_KEY = 'sc_workspace_last_good_v1'" in js and 'function captureLastGoodSnapshot()' in js,'v0.20 last-known-good recovery retained')
check('@media(prefers-reduced-motion:reduce)' in css and '@media(forced-colors:active)' in css and ':focus-visible' in css,'accessibility hardening retained')
